using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageFormatterTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    [Fact]
    public async Task IntKeyFormatter_IsExcludedFromCodeCoverage()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [MessagePackObject]
                public class IntKeyed
                {
                    [Key(0)]
                    public int A { get; set; }

                    [Key(1)]
                    public string B { get; set; } = "";
                }
            }
            """;
        await AssertAllFormattersExcludedAsync(source);
    }

    [Fact]
    public async Task StringKeyFormatter_IsExcludedFromCodeCoverage()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [MessagePackObject]
                public class StringKeyed
                {
                    [Key("a")]
                    public int A { get; set; }

                    [Key("b")]
                    public string B { get; set; } = "";
                }
            }
            """;
        await AssertAllFormattersExcludedAsync(source);
    }

    [Fact]
    public async Task UnionFormatter_IsExcludedFromCodeCoverage()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [Union(0, typeof(UnionA))]
                [Union(1, typeof(UnionB))]
                public interface IUnionBase { }

                [MessagePackObject]
                public class UnionA : IUnionBase
                {
                    [Key(0)]
                    public int X { get; set; }
                }

                [MessagePackObject]
                public class UnionB : IUnionBase
                {
                    [Key(0)]
                    public int Y { get; set; }
                }
            }
            """;
        await AssertAllFormattersExcludedAsync(source);
    }

    [Fact]
    public async Task EnumAndObjectFormatters_AreExcludedFromCodeCoverage()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                public enum Color
                {
                    Red,
                    Green,
                }

                [MessagePackObject]
                public class HasEnum
                {
                    [Key(0)]
                    public Color C { get; set; }
                }
            }
            """;
        await AssertAllFormattersExcludedAsync(source);
    }

    private static async Task AssertAllFormattersExcludedAsync(string source)
    {
        List<INamedTypeSymbol> formatters = await GetGeneratedFormattersAsync(source);
        Assert.NotEmpty(formatters);
        foreach (INamedTypeSymbol formatter in formatters)
        {
            Assert.True(HasExcludeFromCodeCoverage(formatter), $"Generated formatter {formatter.ToDisplayString()} is not decorated with [ExcludeFromCodeCoverage].");
        }
    }

    private static bool HasExcludeFromCodeCoverage(INamedTypeSymbol symbol)
        => symbol.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName);

    private static async Task<List<INamedTypeSymbol>> GetGeneratedFormattersAsync(string source)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = new List<MetadataReference>(framework);
        references.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        SyntaxTree inputTree = CSharpSyntaxTree.ParseText(source, parseOptions);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsFormatterAssembly",
            new[] { inputTree },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator()).WithUpdatedParseOptions(parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);

        List<INamedTypeSymbol> result = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in output.SyntaxTrees.Where(t => !ReferenceEquals(t, inputTree)))
        {
            SemanticModel model = output.GetSemanticModel(tree);
            SyntaxNode root = await tree.GetRootAsync();
            foreach (TypeDeclarationSyntax declaration in root.DescendantNodes().OfType<TypeDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(declaration) is INamedTypeSymbol symbol
                    && symbol.AllInterfaces.Any(i => i.OriginalDefinition.ToDisplayString().StartsWith("MessagePack.Formatters.IMessagePackFormatter<", StringComparison.Ordinal)))
                {
                    result.Add(symbol);
                }
            }
        }

        return result;
    }
}

