using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageScopeTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    private const string Source = """
        using MessagePack;

        namespace TestNs
        {
            [GeneratedMessagePackResolver]
            partial class MyResolver { }

            [MessagePackObject]
            public class IntKeyed
            {
                [Key(0)]
                public int A { get; set; }
            }
        }
        """;

    [Fact]
    public async Task GeneratedResolver_IsExcludedFromCodeCoverage()
    {
        (Compilation output, _) = await RunGeneratorAsync(Source);
        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("TestNs.MyResolver");
        Assert.NotNull(resolver);
        Assert.True(HasExcludeFromCodeCoverage(resolver!), "Generated resolver TestNs.MyResolver is not decorated with [ExcludeFromCodeCoverage].");
    }

    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task Formatters_AreExcludedFromCodeCoverage_ForTargetFrameworkSymbol(string symbol)
    {
        (Compilation output, List<SyntaxTree> generated) = await RunGeneratorAsync(Source, symbol);
        List<INamedTypeSymbol> formatters = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in generated)
        {
            SemanticModel model = output.GetSemanticModel(tree);
            SyntaxNode root = await tree.GetRootAsync();
            foreach (TypeDeclarationSyntax declaration in root.DescendantNodes().OfType<TypeDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(declaration) is INamedTypeSymbol type
                    && type.AllInterfaces.Any(i => i.OriginalDefinition.ToDisplayString().StartsWith("MessagePack.Formatters.IMessagePackFormatter<", StringComparison.Ordinal)))
                {
                    formatters.Add(type);
                }
            }
        }

        Assert.NotEmpty(formatters);
        foreach (INamedTypeSymbol formatter in formatters)
        {
            Assert.True(HasExcludeFromCodeCoverage(formatter), $"Formatter {formatter.ToDisplayString()} lacks [ExcludeFromCodeCoverage] when {symbol} is defined.");
        }
    }

    private static bool HasExcludeFromCodeCoverage(INamedTypeSymbol symbol)
        => symbol.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName);

    private static async Task<(Compilation Output, List<SyntaxTree> Generated)> RunGeneratorAsync(string source, params string[] preprocessorSymbols)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: preprocessorSymbols);
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = new List<MetadataReference>(framework);
        references.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        SyntaxTree inputTree = CSharpSyntaxTree.ParseText(source, parseOptions);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsScopeAssembly",
            new[] { inputTree },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator()).WithUpdatedParseOptions(parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);
        List<SyntaxTree> generated = output.SyntaxTrees.Where(t => !ReferenceEquals(t, inputTree)).ToList();
        return (output, generated);
    }
}
